dashboard.definition:
{
  "title": "Threat Detection",
  "description": "Suricata IDS alerts and L7 inline IPS verdicts, pivoted on the affected workload and the external peer, with MITRE ATT&CK context.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "time",
        "defaultValue": "-7d@h,now"
      }
    },
    "input_gateway": {
      "type": "input.dropdown",
      "title": "Gateway",
      "dataSources": {
        "primary": "ds_input_gateway"
      },
      "options": {
        "token": "gateway",
        "defaultValue": "*",
        "items": ">frame(label, value) | prepend(formattedStatics) | objects()"
      },
      "encoding": {
        "label": "primary[0]",
        "value": "primary[1]"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "formattedStatics": ">statics | formatByType(formattedConfig)",
        "statics": [
          [
            "All gateways"
          ],
          [
            "*"
          ]
        ],
        "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    },
    "input_severity": {
      "type": "input.dropdown",
      "title": "Severity",
      "options": {
        "token": "severity",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          },
          {
            "label": "Critical",
            "value": "1"
          },
          {
            "label": "High",
            "value": "2"
          },
          {
            "label": "Medium",
            "value": "3"
          },
          {
            "label": "Low",
            "value": "4"
          }
        ]
      }
    },
    "input_engine": {
      "type": "input.dropdown",
      "title": "Engine",
      "options": {
        "token": "engine",
        "defaultValue": "*",
        "items": [
          {
            "label": "All",
            "value": "*"
          },
          {
            "label": "Suricata IDS",
            "value": "Suricata IDS"
          },
          {
            "label": "L7 inline IPS",
            "value": "L7 inline IPS"
          }
        ]
      }
    },
    "input_signature": {
      "type": "input.text",
      "title": "Signature",
      "options": {
        "token": "signature",
        "defaultValue": "*"
      }
    },
    "input_asset": {
      "type": "input.text",
      "title": "Asset IP (either side)",
      "options": {
        "token": "asset",
        "defaultValue": "*"
      }
    },
    "input_src_ip": {
      "type": "input.text",
      "title": "Source IP",
      "options": {
        "token": "src_ip",
        "defaultValue": "*"
      }
    },
    "input_dest_ip": {
      "type": "input.text",
      "title": "Destination IP",
      "options": {
        "token": "dest_ip",
        "defaultValue": "*"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$time.earliest$",
            "latest": "$time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_10": {
      "type": "splunk.singlevalue",
      "title": "Alerts",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3987e5",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_11": {
      "type": "splunk.singlevalue",
      "title": "Critical + high",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#d03b3b",
        "majorColor": "> majorValue | rangeValue(alertColors)",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      },
      "context": {
        "alertColors": [
          {
            "to": 1,
            "value": "#f0efec"
          },
          {
            "from": 1,
            "value": "#d03b3b"
          }
        ]
      }
    },
    "viz_12": {
      "type": "splunk.singlevalue",
      "title": "Blocked inline",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"total\") | lastPoint()",
        "sparklineValues": "> primary | seriesByName(\"value\")",
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#3987e5",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      },
      "description": "Dropped by IPS"
    },
    "viz_13": {
      "type": "splunk.singlevalue",
      "title": "Signatures",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "majorColor": "#f0efec",
        "backgroundColor": "#17181b",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 34
      }
    },
    "viz_14": {
      "type": "splunk.singlevalue",
      "title": "Internal hosts",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "majorValue": "> primary | seriesByName(\"value\") | lastPoint()",
