    "viz_18": {
      "type": "splunk.column",
      "title": "Alerts by severity",
      "dataSources": {
        "primary": "ds_16"
      },
      "options": {
        "backgroundColor": "#17181b",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#3987e5",
          "#d95926",
          "#199e70",
          "#c98500",
          "#d55181",
          "#0ca30c",
          "#9085e9",
          "#e66767"
        ],
        "yAxisTitleVisibility": "hide",
        "seriesColorsByField": {
          "Critical": "#d03b3b",
          "High": "#ec835a",
          "Medium": "#fab219",
          "Low": "#3987e5",
          "Info": "#6b6f76"
        },
        "stackMode": "stacked"
      }
    },
    "viz_19": {
      "type": "splunk.bar",
      "title": "MITRE ATT&CK tactics",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "backgroundColor": "#17181b",
        "legendDisplay": "off",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
