            "value": "#ff8a85"
          },
          {
            "match": "created",
            "value": "#4cc94c"
          },
          {
            "match": "modified",
            "value": "#86b6ef"
          },
          {
            "match": "deleted",
            "value": "#ff8a85"
          },
          {
            "match": "read",
            "value": "#898781"
          },
          {
            "match": "active",
            "value": "#4cc94c"
          },
          {
            "match": "disconnected",
            "value": "#898781"
          }
        ]
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "type": "auto",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_input_gateway": {
      "type": "ds.search",
      "name": "ds_input_gateway",
      "options": {
        "query": "| tstats count where `aviatrix_index` (sourcetype=\"aviatrix:ids\" OR sourcetype=\"aviatrix:firewall:l7\") by host\n| sort - count | head 300\n| eval label=host, value=host | fields label value",
        "queryParameters": {
          "earliest": "$time.earliest$",
          "latest": "$time.latest$"
        }
      }
    },
    "ds_threat_time": {
      "type": "ds.search",
      "name": "ds_threat_time",
      "options": {
        "query": "`aviatrix_threats` host=$gateway$\n| `aviatrix_threat_fields`\n| search severity_id=$severity$ engine=$engine|s$ signature=$signature|s$ src=$src_ip$ dest=$dest_ip$ (src=$asset$ OR dest=$asset$)\n| bin _time bins=100\n| stats count by _time sev_label threat_outcome"
      }
    },
    "ds_threat_agg": {
      "type": "ds.search",
      "name": "ds_threat_agg",
      "options": {
        "query": "`aviatrix_threats` host=$gateway$\n| `aviatrix_threat_fields`\n| search severity_id=$severity$ engine=$engine|s$ signature=$signature|s$ src=$src_ip$ dest=$dest_ip$ (src=$asset$ OR dest=$asset$)\n| stats count min(_time) as first max(_time) as last values(category) as category values(tactic) as tactic values(mitre_technique) as technique values(domain) as domain by signature sid severity_id sev_label engine threat_outcome internal_host peer host"
      }
    },
    "ds_4": {
      "type": "ds.chain",
      "name": "ds_4",
      "options": {
        "extend": "ds_threat_time",
        "query": "| timechart sum(count) as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_5": {
      "type": "ds.chain",
      "name": "ds_5",
      "options": {
        "extend": "ds_threat_time",
        "query": "| where sev_label=\"Critical\" OR sev_label=\"High\"\n| timechart sum(count) as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_6": {
      "type": "ds.chain",
      "name": "ds_6",
      "options": {
        "extend": "ds_threat_time",
        "query": "| where threat_outcome=\"Blocked\"\n| timechart sum(count) as value\n| fillnull value=0 value\n| eventstats sum(value) as total\n| appendpipe [| stats count as n | where n=0 | eval value=0, total=0 | fields value total]"
      }
    },
    "ds_7": {
      "type": "ds.chain",
      "name": "ds_7",
      "options": {
        "extend": "ds_threat_agg",
        "query": "| stats dc(signature) as value"
      }
    },
    "ds_8": {
      "type": "ds.chain",
      "name": "ds_8",
      "options": {
        "extend": "ds_threat_agg",
        "query": "| stats dc(internal_host) as value"
      }
    },
    "ds_9": {
      "type": "ds.chain",
      "name": "ds_9",
      "options": {
        "extend": "ds_threat_agg",
        "query": "| where NOT `aviatrix_private_ip(peer)` | stats dc(peer) as value"
      }
    },
    "ds_16": {
      "type": "ds.chain",
      "name": "ds_16",
      "options": {
        "extend": "ds_threat_time",
        "query": "| timechart sum(count) by sev_label"
      }
    },
    "ds_17": {
      "type": "ds.chain",
      "name": "ds_17",
      "options": {
        "extend": "ds_threat_agg",
        "query": "| mvexpand tactic\n| stats sum(count) as Alerts by tactic\n| sort - Alerts"
      }
    },
    "ds_21": {
      "type": "ds.chain",
      "name": "ds_21",
      "options": {
        "extend": "ds_threat_agg",
        "query": "| stats sum(count) as Alerts dc(internal_host) as Hosts dc(peer) as Peers values(category) as category values(engine) as Engine values(threat_outcome) as outcome min(first) as first max(last) as last by signature sid severity_id sev_label\n| eval Outcome=mvjoin(outcome, \" / \"), Category=mvindex(category, 0), First=strftime(first, \"%Y-%m-%d %H:%M\"), Last=strftime(last, \"%Y-%m-%d %H:%M\")\n| sort severity_id - Alerts\n| rename sev_label as Severity, signature as Signature, sid as SID\n| table Severity Signature SID Category Engine Outcome Alerts Hosts Peers First Last"
      }
    },
    "ds_24": {
      "type": "ds.chain",
      "name": "ds_24",
      "options": {
        "extend": "ds_threat_agg",
        "query": "| stats sum(count) as Alerts min(severity_id) as sev dc(signature) as Signatures values(signature) as sigs dc(peer) as Peers max(last) as last by internal_host\n| eval Severity=`aviatrix_severity_label(sev)`, \"Top signature\"=mvindex(sigs, 0), \"Last alert\"=strftime(last, \"%Y-%m-%d %H:%M\")\n| sort sev - Alerts\n| rename internal_host as Host\n| table Host Severity Alerts Signatures Peers \"Top signature\" \"Last alert\""
      }
    },
    "ds_25": {
      "type": "ds.chain",
      "name": "ds_25",
      "options": {
        "extend": "ds_threat_agg",
        "query": "| where NOT `aviatrix_private_ip(peer)`\n| stats sum(count) as Alerts min(severity_id) as sev dc(signature) as Signatures dc(internal_host) as Hosts values(domain) as dom by peer\n| iplocation peer\n| eval Severity=`aviatrix_severity_label(sev)`, Location=coalesce(nullif(mvjoin(mvappend(nullif(City, \"\"), nullif(Country, \"\")), \", \"), \"\"), \"-\"), Domain=coalesce(mvindex(dom, 0), \"-\")\n| sort sev - Alerts\n| rename peer as Peer\n| table Peer Domain Location Severity Alerts Signatures Hosts"
      }
    },
    "ds_threat_events": {
      "type": "ds.search",
      "name": "ds_threat_events",
      "options": {
        "query": "`aviatrix_threats` host=$gateway$\n| `aviatrix_threat_fields`\n| search severity_id=$severity$ engine=$engine|s$ signature=$signature|s$ src=$src_ip$ dest=$dest_ip$ (src=$asset$ OR dest=$asset$)\n| head 500\n| eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\"), Source=src.coalesce(\":\".src_port, \"\"), Destination=dest.coalesce(\":\".coalesce(dest_port, dst_port), \"\"), App=coalesce(app, app_proto, transport, \"-\"), Context=coalesce(http_hostname.coalesce(http_url, \"\"), tls_sni, sni_hostname, \"-\")\n| rename sev_label as Severity, signature as Signature, engine as Engine, threat_outcome as Outcome, host as Gateway, tactic as Tactic\n| table Time Severity Signature Engine Outcome Source Destination App Context Tactic Gateway"
      }
    }
  },
